    53→/// Find a crate's directory - tries as path first, then searches standard locations
    54→pub fn find_crate_dir(workspace: &Path, name: &str) -> Result<PathBuf> {
    55→    // Try as path first (relative or absolute)
    56→    let as_path = PathBuf::from(name);
    57→    if as_path.join("Cargo.toml").exists() {
    58→        return Ok(as_path.canonicalize().unwrap_or(as_path));
    59→    }
    60→
    61→    // Fallback: search libs/, apps/, tools/
    62→    for prefix in ["libs", "apps", "tools"] {
    63→        let path = workspace.join(prefix).join(name);
    64→        if path.join("Cargo.toml").exists() {
    65→            return Ok(path);
    66→        }
    67→    }
    68→
    69→    // Special case: nested test crates like libs/rlibc-x2/tests
    70→    for prefix in ["libs", "apps"] {
    71→        for entry in std::fs::read_dir(workspace.join(prefix)).into_iter().flatten() {
    72→            if let Ok(entry) = entry {
    73→                let nested = entry.path().join("tests");
    74→                if nested.join("Cargo.toml").exists() {
    75→                    // Check if this is the crate we're looking for
    76→                    if let Ok(pkg_name) = get_crate_name(&nested) {
    77→                        if pkg_name == name {
    78→                            return Ok(nested);
    79→                        }
    80→                    }
    81→                }
    82→            }
    83→        }
    84→    }
    85→
    86→    bail!("crate '{}' not found", name);
    87→}
