    89→/// Find the tspec for a crate - tries as path first, then relative to crate_dir
    90→/// Returns None if no tspec exists (plain cargo build will be used)
    91→pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    92→    match explicit {
    93→        Some(name) => {
    94→            // Try as path first (relative to cwd or absolute)
    95→            let as_path = PathBuf::from(name);
    96→            if as_path.exists() {
    97→                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
    98→            }
    99→
   100→            // Fallback: relative to crate directory
   101→            let in_crate = crate_dir.join(name);
   102→            if in_crate.exists() {
   103→                return Ok(Some(in_crate));
   104→            }
   105→
   106→            // Try with .xt.toml suffix if name has no extension
   107→            if !name.contains('.') {
   108→                let with_suffix = crate_dir.join(format!("{}.xt.toml", name));
   109→                if with_suffix.exists() {
   110→                    return Ok(Some(with_suffix));
   111→                }
   112→            }
   113→
   114→            bail!("tspec not found: {}", name);
   115→        }
   116→        None => {
   117→            let default = crate_dir.join("tspec.xt.toml");
   118→            if default.exists() {
   119→                Ok(Some(default))
   120→            } else {
   121→                Ok(None) // No tspec = plain cargo build
   122→            }
   123→        }
   124→    }
   125→}
