   127→/// Get binary path for a build with a spec
   128→pub fn get_binary_path(workspace: &Path, crate_name: &str, spec: &Spec, release: bool) -> PathBuf {
   129→    let is_release = release
   130→        || spec
   131→            .cargo
   132→            .iter()
   133→            .any(|p| matches!(p, CargoParam::Profile(Profile::Release)));
   134→
   135→    let target = spec.cargo.iter().find_map(|p| match p {
   136→        CargoParam::TargetTriple(t) => Some(t.clone()),
   137→        CargoParam::TargetJson(p) => p.file_stem().map(|s| s.to_string_lossy().to_string()),
   138→        _ => None,
   139→    });
   140→
   141→    let profile_dir = if is_release { "release" } else { "debug" };
   142→
   143→    match target {
   144→        Some(t) => workspace
   145→            .join("target")
   146→            .join(t)
   147→            .join(profile_dir)
   148→            .join(crate_name),
   149→        None => workspace.join("target").join(profile_dir).join(crate_name),
   150→    }
   151→}
   152→
   153→/// Get binary path for a simple build (no spec)
   154→pub fn get_binary_path_simple(workspace: &Path, crate_name: &str, release: bool) -> PathBuf {
   155→    let profile_dir = if release { "release" } else { "debug" };
   156→    workspace.join("target").join(profile_dir).join(crate_name)
   157→}
